-- A05 isolated SQL assertions. No real accounts, passwords, customer data or persistent QA records.
DO $qa$
DECLARE b1 uuid:=gen_random_uuid();b2 uuid:=gen_random_uuid();m uuid:=gen_random_uuid();c uuid:=gen_random_uuid();cs uuid:=gen_random_uuid();duser uuid:=gen_random_uuid();su uuid:=gen_random_uuid();ap uuid:=gen_random_uuid();reject_ap uuid:=gen_random_uuid();app uuid:=gen_random_uuid();app2 uuid:=gen_random_uuid();cust uuid:=gen_random_uuid();d1 uuid:=gen_random_uuid();d2 uuid:=gen_random_uuid();o1 uuid:=gen_random_uuid();o2 uuid:=gen_random_uuid();o3 uuid:=gen_random_uuid();ph text:='+999'||lpad(floor(random()*1e9)::bigint::text,9,'0');ph2 text:='+998'||lpad(floor(random()*1e9)::bigint::text,9,'0');r jsonb;blocked boolean;passes int:=0;actor uuid;
BEGIN
 BEGIN
 INSERT INTO public.ff_branches(id,code,name) VALUES(b1,'qa-'||b1,'QA branch 1'),(b2,'qa-'||b2,'QA branch 2');
 INSERT INTO auth.users(id,email) SELECT u,'qa-'||u||'@example.invalid' FROM unnest(ARRAY[m,c,cs,duser,su]) u;
 INSERT INTO auth.users(id,email,phone) VALUES(ap,'qa-'||ap||'@example.invalid',ph),(reject_ap,'qa-'||reject_ap||'@example.invalid',ph2);
 INSERT INTO public.ff_profiles(user_id,display_name,role,active) VALUES(m,'QA manager','manager',true),(c,'QA cashier','cashier',true),(cs,'QA CS','customer_service',true),(duser,'QA driver','driver',true),(su,'QA supervisor','supervisor',true) ON CONFLICT(user_id) DO UPDATE SET role=excluded.role,active=true;
 INSERT INTO public.ff_user_branches(user_id,branch_id) VALUES(c,b1),(su,b2);
 INSERT INTO public.ff61_employee_applications(id,full_name,phone,qualification,address,age_years,marital_status,requested_role,privacy_accepted_at) VALUES(app,'QA Applicant',ph,'QA','QA address',25,'prefer_not_say','cashier',now()),(app2,'QA Reject',ph2,'QA','QA address',25,'single','driver',now());
 IF EXISTS(SELECT 1 FROM public.ff_profiles WHERE user_id IN(ap,reject_ap)) OR NOT EXISTS(SELECT 1 FROM public.ff61_employee_applications WHERE id=app AND status='pending') THEN RAISE EXCEPTION 'Pending automatically activated';END IF;passes:=passes+1;
 PERFORM set_config('request.jwt.claim.sub',ap::text,true);SET LOCAL ROLE authenticated;
 blocked:=false;BEGIN PERFORM public.ff38_snapshot();EXCEPTION WHEN SQLSTATE '42501' THEN blocked:=true;END;
 IF NOT blocked THEN RAISE EXCEPTION 'Applicant accessed workspace';END IF;passes:=passes+1;
 blocked:=false;BEGIN PERFORM public.ff61_approve_application(app,ap,ap,'cashier',b1);EXCEPTION WHEN SQLSTATE '42501' THEN blocked:=true;END;
 IF NOT blocked THEN RAISE EXCEPTION 'Applicant called approval RPC';END IF;passes:=passes+1;
 RESET ROLE;
 PERFORM set_config('request.jwt.claim.sub',m::text,true);SET LOCAL ROLE authenticated;
 blocked:=false;BEGIN UPDATE public.ff_profiles SET active=false WHERE user_id=m;EXCEPTION WHEN SQLSTATE '42501' THEN blocked:=true;END;
 IF NOT blocked THEN RAISE EXCEPTION 'Direct manager profile update allowed';END IF;passes:=passes+1;
 blocked:=false;BEGIN INSERT INTO public.ff_user_branches(user_id,branch_id) VALUES(c,b2);EXCEPTION WHEN SQLSTATE '42501' THEN blocked:=true;END;
 IF NOT blocked THEN RAISE EXCEPTION 'Direct branch grant allowed';END IF;passes:=passes+1;
 blocked:=false;BEGIN PERFORM public.ff38_admin_link_user('qa-'||ap||'@example.invalid','QA Applicant','cashier',b1);EXCEPTION WHEN SQLSTATE '42501' THEN blocked:=true;END;
 IF NOT blocked THEN RAISE EXCEPTION 'Legacy linking bypassed application';END IF;passes:=passes+1;
 PERFORM public.ff61_set_delegation(cs,true,false,false,true);
 PERFORM public.ff38_admin_set_permission(c,'edit_order',true);
 RESET ROLE;
 IF NOT public.ff61_can_act(cs,'view') OR NOT public.ff61_can_act(cs,'notify') OR public.ff61_can_act(cs,'approve') OR public.ff61_can_act(cs,'reject') THEN RAISE EXCEPTION 'Independent delegation mismatch';END IF;passes:=passes+1;
 blocked:=false;BEGIN PERFORM public.ff61_approve_application(app,cs,ap,'cashier',b1);EXCEPTION WHEN SQLSTATE '42501' THEN blocked:=true;END;
 IF NOT blocked THEN RAISE EXCEPTION 'View-only delegate approved';END IF;passes:=passes+1;
 blocked:=false;BEGIN PERFORM public.ff61_reject_application(app2,cs,'QA reason');EXCEPTION WHEN SQLSTATE '42501' THEN blocked:=true;END;
 IF NOT blocked THEN RAISE EXCEPTION 'View-only delegate rejected';END IF;passes:=passes+1;
 PERFORM set_config('request.jwt.claim.sub',m::text,true);SET LOCAL ROLE authenticated;
 PERFORM public.ff61_set_delegation(cs,false,true,false,false);RESET ROLE;
 blocked:=false;BEGIN PERFORM public.ff61_approve_application(app,cs,ap,'cashier',NULL);EXCEPTION WHEN raise_exception THEN blocked:=true;END;
 IF NOT blocked THEN RAISE EXCEPTION 'Approval without branch';END IF;passes:=passes+1;
 blocked:=false;BEGIN PERFORM public.ff61_approve_application(app,cs,reject_ap,'cashier',b1);EXCEPTION WHEN raise_exception THEN blocked:=true;END;
 IF NOT blocked THEN RAISE EXCEPTION 'Approval phone mismatch';END IF;passes:=passes+1;
 r:=public.ff61_approve_application(app,cs,ap,'cashier',b1);
 IF r->>'approved'<>'true' OR NOT EXISTS(SELECT 1 FROM public.ff_profiles WHERE user_id=ap AND active AND role='cashier') OR NOT EXISTS(SELECT 1 FROM public.ff_user_branches WHERE user_id=ap AND branch_id=b1) THEN RAISE EXCEPTION 'Approved role/branch not saved';END IF;passes:=passes+1;
 blocked:=false;BEGIN PERFORM public.ff61_approve_application(app,cs,ap,'cashier',b1);EXCEPTION WHEN raise_exception THEN blocked:=true;END;
 IF NOT blocked THEN RAISE EXCEPTION 'Duplicate approval accepted';END IF;passes:=passes+1;
 PERFORM set_config('request.jwt.claim.sub',m::text,true);SET LOCAL ROLE authenticated;
 PERFORM public.ff61_set_delegation(cs,false,false,true,false);RESET ROLE;
 blocked:=false;BEGIN PERFORM public.ff61_reject_application(app2,cs,'x');EXCEPTION WHEN raise_exception THEN blocked:=true;END;
 IF NOT blocked THEN RAISE EXCEPTION 'Rejection without valid reason';END IF;passes:=passes+1;
 PERFORM public.ff61_reject_application(app2,cs,'QA valid reason');
 IF NOT EXISTS(SELECT 1 FROM public.ff61_employee_applications WHERE id=app2 AND status='rejected' AND decision_reason='QA valid reason') OR EXISTS(SELECT 1 FROM public.ff_profiles WHERE user_id=reject_ap) THEN RAISE EXCEPTION 'Rejection activated account';END IF;passes:=passes+1;
 -- Scope raw customer and order rows: two branches, one cashier assignment, driver owns only one task.
 INSERT INTO public.ff_customers(id,phone,name) VALUES(cust,ph,'QA customer');
 INSERT INTO public.ff_customer_notes(customer_id,note,created_by) VALUES(cust,'QA note',m);
 INSERT INTO public.ff_drivers(id,name,branch_id) VALUES(d1,'QA assigned',b1),(d2,'QA other',b2);
 INSERT INTO public.ff38_driver_links(user_id,driver_id) VALUES(duser,d1);
 INSERT INTO public.ff38_driver_presence(driver_id,state,checked_in_at,last_seen_at) VALUES(d1,'busy',now(),now()),(d2,'busy',now(),now()) ON CONFLICT(driver_id) DO UPDATE SET state='busy',checked_in_at=now(),last_seen_at=now();
 INSERT INTO public.ff_orders(id,order_number,branch_id,phone_snapshot,business_date,customer_id,driver_id,status) VALUES
 (o1,-(1+floor(random()*1e12)::bigint),b1,ph,public.ff_business_date(now()),cust,d1,'sent'),
 (o2,-(1+floor(random()*1e12)::bigint),b2,ph,public.ff_business_date(now()),cust,d2,'sent'),
 (o3,-(1+floor(random()*1e12)::bigint),b1,ph,public.ff_business_date(now()),cust,null,'new');
 INSERT INTO public.ff38_delivery_tasks(order_id,driver_id) VALUES(o1,d1),(o2,d2);
 INSERT INTO public.ff_order_items(order_id,item_name,quantity,unit_price,line_total) VALUES(o1,'QA',1,100,100),(o2,'QA',1,100,100),(o3,'QA',1,100,100);
 PERFORM set_config('request.jwt.claim.sub',c::text,true);SET LOCAL ROLE authenticated;
 IF (SELECT count(*) FROM public.ff_orders WHERE id IN(o1,o2,o3))<>1 OR NOT EXISTS(SELECT 1 FROM public.ff_orders WHERE id=o1) OR (SELECT count(*) FROM public.ff_order_items WHERE order_id IN(o1,o2,o3))<>1 THEN RAISE EXCEPTION 'Cashier raw scope';END IF;passes:=passes+1;
 IF EXISTS(SELECT 1 FROM public.ff_customers WHERE id=cust) OR EXISTS(SELECT 1 FROM public.ff_customer_notes WHERE customer_id=cust) THEN RAISE EXCEPTION 'Cashier raw customer directory leaked';END IF;passes:=passes+1;
 IF NOT public.ff38_permission_allowed(c,'edit_order') THEN RAISE EXCEPTION 'Granted override missing';END IF;passes:=passes+1;
 blocked:=false;BEGIN PERFORM public.ff38_admin_set_permission(c,'edit_order',true);EXCEPTION WHEN SQLSTATE '42501' THEN blocked:=true;END;
 IF NOT blocked THEN RAISE EXCEPTION 'Self permission edit allowed';END IF;passes:=passes+1;
 blocked:=false;BEGIN PERFORM public.ff_order_customer_read(o2);EXCEPTION WHEN SQLSTATE '42501' THEN blocked:=true;END;
 IF NOT blocked THEN RAISE EXCEPTION 'Cross branch RPC read';END IF;passes:=passes+1;
 RESET ROLE;
 PERFORM set_config('request.jwt.claim.sub',duser::text,true);SET LOCAL ROLE authenticated;
 IF (SELECT count(*) FROM public.ff_orders WHERE id IN(o1,o2,o3))<>1 OR NOT EXISTS(SELECT 1 FROM public.ff_orders WHERE id=o1) OR EXISTS(SELECT 1 FROM public.ff_customers WHERE id=cust) THEN RAISE EXCEPTION 'Driver own-task scope';END IF;passes:=passes+1;
 RESET ROLE;
 PERFORM set_config('request.jwt.claim.sub',cs::text,true);SET LOCAL ROLE authenticated;
 IF (SELECT count(*) FROM public.ff_orders WHERE id IN(o1,o2,o3))<>3 OR NOT EXISTS(SELECT 1 FROM public.ff_customers WHERE id=cust) THEN RAISE EXCEPTION 'Central CS scope lost';END IF;passes:=passes+1;
 RESET ROLE;
 PERFORM set_config('request.jwt.claim.sub',m::text,true);SET LOCAL ROLE authenticated;
 PERFORM public.ff38_admin_set_permission(c,'edit_order',false);
 PERFORM public.ff38_admin_set_permission(cs,'assign_driver',false);
 RESET ROLE;
 PERFORM set_config('request.jwt.claim.sub',c::text,true);SET LOCAL ROLE authenticated;
 blocked:=false;BEGIN PERFORM public.ff_order_customer_read(o1);EXCEPTION WHEN SQLSTATE '42501' THEN blocked:=true;END;
 IF NOT blocked THEN RAISE EXCEPTION 'Revoked edit permission not enforced';END IF;passes:=passes+1;
 RESET ROLE;
 PERFORM set_config('request.jwt.claim.sub',cs::text,true);SET LOCAL ROLE authenticated;
 blocked:=false;BEGIN PERFORM public.ff38_sweep_offers();EXCEPTION WHEN SQLSTATE '42501' THEN blocked:=true;END;
 IF NOT blocked THEN RAISE EXCEPTION 'Revoked dispatch via sweep';END IF;passes:=passes+1;
 RESET ROLE;
 PERFORM set_config('request.jwt.claim.sub',m::text,true);SET LOCAL ROLE authenticated;
 PERFORM public.ff68_admin_staff_set_role(cs,'cashier',ARRAY[b2]);
 RESET ROLE;
 IF EXISTS(SELECT 1 FROM public.ff38_staff_permission_overrides WHERE user_id=cs) OR public.ff61_can_act(cs,'reject') OR EXISTS(SELECT 1 FROM public.ff61_application_delegations WHERE user_id=cs) THEN RAISE EXCEPTION 'Stale permissions/delegations after role change';END IF;passes:=passes+1;
 PERFORM set_config('request.jwt.claim.sub',m::text,true);SET LOCAL ROLE authenticated;
 PERFORM public.ff38_admin_staff_set_active(c,false);RESET ROLE;
 PERFORM set_config('request.jwt.claim.sub',c::text,true);SET LOCAL ROLE authenticated;
 IF public.ff38_permission_allowed(c,'edit_order') OR EXISTS(SELECT 1 FROM public.ff_orders WHERE id=o1) THEN RAISE EXCEPTION 'Suspended account retains access';END IF;passes:=passes+1;
 blocked:=false;BEGIN PERFORM public.ff38_snapshot();EXCEPTION WHEN SQLSTATE '42501' THEN blocked:=true;END;
 IF NOT blocked THEN RAISE EXCEPTION 'Disabled snapshot allowed';END IF;passes:=passes+1;
 RESET ROLE;
 IF (SELECT count(*) FROM public.ff_audit_log WHERE action IN('ff61_application_approved','ff61_application_rejected') AND entity_id IN(app::text,app2::text))<>2 THEN RAISE EXCEPTION 'Decision audit missing';END IF;passes:=passes+1;
 IF EXISTS(SELECT 1 FROM public.ff_profiles WHERE user_id=reject_ap) THEN RAISE EXCEPTION 'Rejected account exists';END IF;passes:=passes+1;
 IF EXISTS(SELECT 1 FROM public.ff61_employee_applications WHERE id IN(app,app2) AND decision_reason IS NULL) THEN RAISE EXCEPTION 'Decision reason missing';END IF;passes:=passes+1;
 RAISE EXCEPTION 'QA rollback sentinel' USING ERRCODE='ZQ001';
 EXCEPTION WHEN SQLSTATE 'ZQ001' THEN NULL;END;
 IF passes<>30 OR EXISTS(SELECT 1 FROM public.ff_branches WHERE id IN(b1,b2)) OR EXISTS(SELECT 1 FROM auth.users WHERE id IN(m,c,cs,duser,su,ap,reject_ap)) OR EXISTS(SELECT 1 FROM public.ff61_employee_applications WHERE id IN(app,app2)) THEN RAISE EXCEPTION 'Incomplete QA or rollback: %',passes;END IF;
END $qa$;
SELECT 'PASS A05: 30 assertions, binary name onboarding, approval/reject/delegation, guarded role changes and raw read scope, immediate revocation; rollback' AS result;